/* Audited local-preview controls. Server-backed staff controls live in staff.html. */
const workspaceDialog=newDialog('workspace-help-dialog',`<div class="modal-heading"><h2>Workspace &amp; help</h2><button type="button" class="close" aria-label="Close workspace help">×</button></div><p>Use fictional information in this care-workspace preview. Its records stay in this browser.</p><div class="workspace-links"><a href="staff.html">Open shared staff scheduler →</a><a href="index.html?portal=client">Client intake preview →</a><a href="about-eero.html">Eero services &amp; contact →</a><a href="kemi-idowu.html">Meet Kemi Idowu →</a></div><p>Use Search workspace or ⌘/Ctrl K to find cases, documents and actions. Use the Calendar to plan sessions and Tasks to track follow-ups.</p><p>The shared staff scheduler uses its own sign-in and server data; local sample records are not automatically copied there.</p>`);
document.querySelector('header .avatar').onclick=()=>workspaceDialog.showModal();document.querySelector('header .avatar').setAttribute('aria-label','Workspace and help');
let editingLocalCase=null,editingLocalTask=null;
$('new-case').onclick=()=>{editingLocalCase=null;$('case-form').reset();$('case-modal').querySelector('h2').textContent='Create a case folder';$('case-modal').showModal()};
$('case-form').onsubmit=async e=>{e.preventDefault();const label=$('case-label').value.trim();if(!label)return;if(editingLocalCase){const c=state.cases.find(c=>c.id===editingLocalCase);c.label=label;c.service=$('case-service').value}else state.cases.push({id:uid(),label,service:$('case-service').value});await persist();$('case-modal').close();currentView='cases';render();toast(editingLocalCase?'Case updated.':'Case folder created.')};
function editLocalCase(id){const c=state.cases.find(c=>c.id===id);if(!c)return;editingLocalCase=id;$('case-label').value=c.label;$('case-service').value=c.service;$('case-modal').querySelector('h2').textContent='Edit case folder';$('case-modal').showModal()}
const auditedOpenCase=openCase;openCase=function(id){auditedOpenCase(id);$('profile-content').querySelector('.profile-actions').insertAdjacentHTML('beforeend','<button class="secondary" id="profile-chart">Open chart</button><button class="secondary" id="profile-session">Plan session</button><button class="secondary" id="profile-task">Plan follow-up</button><button class="secondary" id="profile-edit-case">Edit case</button>');$('profile-chart').onclick=()=>{caseProfile.close();selectedChartCase=id;selectedChartTab='overview';currentView='chart';render()};$('profile-session').onclick=()=>{caseProfile.close();openSession();$('session-case').value=id};$('profile-task').onclick=()=>{caseProfile.close();$('task-open').click();$('task-case').value=id};$('profile-edit-case').onclick=()=>{caseProfile.close();editLocalCase(id)}};
const auditedTaskOpen=$('task-open').onclick;$('task-open').onclick=()=>{editingLocalTask=null;auditedTaskOpen();$('task-modal').querySelector('h2').textContent='Plan a follow-up'};
$('task-form').onsubmit=async e=>{e.preventDefault();const title=$('task-title').value.trim();if(!title)return;const values={caseId:$('task-case').value,title,due:$('task-due').value};if(editingLocalTask)Object.assign(state.tasks.find(t=>t.id===editingLocalTask),values);else state.tasks.push({id:uid(),...values,done:false});await persist();$('task-modal').close();currentView='tasks';render();toast('Follow-up task saved.')};
const auditedRecordsClick=$('records').onclick;$('records').onclick=async e=>{const edit=e.target.closest('[data-edit-local-task]'),remove=e.target.closest('[data-delete-local-task]');if(edit){const t=state.tasks.find(t=>t.id===edit.dataset.editLocalTask);editingLocalTask=t.id;$('task-case').innerHTML=caseOptions();$('task-case').value=t.caseId;$('task-title').value=t.title;$('task-due').value=t.due;$('task-modal').querySelector('h2').textContent='Edit follow-up';$('task-modal').showModal()}else if(remove){if(!confirm('Delete this sample task?'))return;state.tasks=state.tasks.filter(t=>t.id!==remove.dataset.deleteLocalTask);await persist();toast('Sample task removed.')}else auditedRecordsClick(e)};
const auditedRender=render;render=function(){auditedRender();if(currentView==='tasks'&&portalRole!=='client')$('records').querySelectorAll('[data-task]').forEach(input=>input.closest('.case-row').insertAdjacentHTML('beforeend',`<div class="record-actions"><button class="secondary" data-edit-local-task="${esc(input.dataset.task)}">Edit task</button><button class="secondary" data-delete-local-task="${esc(input.dataset.task)}">Delete task</button></div>`));document.querySelectorAll('aside [data-view]').forEach(b=>b.setAttribute('aria-current',b.dataset.view===currentView?'page':'false'))};
for(const input of document.querySelectorAll('input[type=file]'))input.accept=input.hasAttribute('capture')?'image/jpeg,image/png':'image/jpeg,image/png,application/pdf';
if(state)render();
